+        .await
+        .expect("attach");
+    let start_end = match &attach.attach_resp {
+        DaemonResponse::AttachOk { end_sequence, .. } => *end_sequence,
+        other => panic!("Expected AttachOk, got {other:?}"),
+    };
+
+    let mut last_seq = start_end.unwrap_or(0);
+    client
+        .write_input(
