fn extract_pid_and_ppid(output: &str) -> Option<(u32, u32)> {
    for part in output.split("__PID__") {
        if let Some((pid_str, rest)) = part.split_once("__PPID__") {
            if let Some((ppid_str, _)) = rest.split_once("__END__") {
                let pid_str_clean: String =
                    pid_str.chars().filter(|c| c.is_ascii_digit()).collect();
                let ppid_str_clean: String =
                    ppid_str.chars().filter(|c| c.is_ascii_digit()).collect();
                if !pid_str_clean.is_empty() && !ppid_str_clean.is_empty() {
                    if let (Ok(pid), Ok(ppid)) =
                        (pid_str_clean.parse::<u32>(), ppid_str_clean.parse::<u32>())
                    {
                        return Some((pid, ppid));
                    }
                }
            }
        }
    }
    None
}

